/**
 * Public server directory — PURE core (no db, no I/O; unit-tested).
 *
 * The directory merges four sources into one list of `DirEntry`:
 *   nxeon-paid       a customer's paid game server that opted in (Server.publicListing)
 *   nxeon-free       a free Minecraft server whose owner made it public
 *   nxeon-community  an Nxeon-run free public server (FreePublicServer)
 *   external         a public server found on a third-party list (ExternalServer,
 *                    ingested from the Steam master list when an admin enabled it)
 *
 * Rules this file owns (growth batch G6, seo-026 owner brief):
 *  1. NO DUPLICATES by connection detail. A connection is a domain or an IP
 *     with an optional port; a missing port means the game's default port, so
 *     `play.x.com`, `play.x.com:25565` and `PLAY.X.COM.` are one server, and so
 *     are `1.2.3.4` and `1.2.3.4:25565` for Minecraft. Entries also carry
 *     SECONDARY keys (an Nxeon server's real node ip:port) so a Valve-list row
 *     for a server we host collapses into our own entry. Two different ports on
 *     one IP are two servers (hosting companies run dozens per IP).
 *  2. Which duplicate survives: Nxeon-hosted beats external; then the one with
 *     an image; then the better-described one; then the most recently seen.
 *     Among external duplicates the survivor inherits a missing image /
 *     description from the losers ("pull whatever you can"); an Nxeon entry is
 *     never edited by third-party data.
 *  3. Entries WITH an image come first, then Nxeon-hosted, then busiest.
 *  4. Indexing (seo-025): a game page is only indexable when enough real,
 *     described, recently-seen servers back it; empty/new ones are noindex.
 */

export type DirSource = "nxeon-paid" | "nxeon-free" | "nxeon-community" | "external";

export type DirEntry = {
  /** Opaque, stable React/DOM key — never a database id. */
  key: string;
  source: DirSource;
  /** Hosted on Nxeon: gets the Nxeon badge. */
  nxeon: boolean;
  /** lib/games.ts GameFamily key. */
  game: string;
  name: string;
  tagline: string;
  description: string;
  /** An https image that is safe to render (owner-approved or first-party). Null otherwise. */
  imageUrl: string | null;
  /** What a player types to join (domain[:port] for Nxeon; ip:port is already public for external). */
  address: string;
  /** Primary dedupe address. */
  host: string;
  port: number | null;
  /** Secondary dedupe addresses (never displayed), e.g. the node ip:port behind a subdomain. */
  alsoKeys: string[];
  players: number | null;
  maxPlayers: number | null;
  country: string | null;
  region: string | null;
  featured: boolean;
  /** Internal page for this server, if it has one. */
  href: string | null;
  /** Owner-supplied website (approved only). Render rel="ugc nofollow noopener". */
  websiteUrl: string | null;
  /** ms epoch the live numbers/entry were last confirmed. */
